  "troll": {"name":"Trol","faction":"enemy","size":2,"darkvision":720,"hp":{"cur":94,"max":94,"temp":0},"ac":15,"speed":30,"initMod":1,"saves":{"str":4,"dex":1,"con":5,"int":-2,"wis":-1,"cha":-2},"actions":[{"id":"multiattack","name":"Multiataque","cost":"action","kind":"attack","range":10,"multi":[{"id":"rend","n":3}]},{"id":"rend","name":"Rend","cost":"action","kind":"attack","range":10,"toHit":7,"damage":"2d6+4","damageType":"slashing"}],"cr":"5","type":"gigante","conditions":[],"sizeName":"Grande","align":"caótico malvado","traits":[{"name":"Loathsome Limbs","text":"If the troll ends any turn Bloodied and took 15+ Slashing damage during that turn, one of the troll’s limbs is severed, falls into the troll’s space, and becomes a Troll Limb. The limb acts immediately after the troll’s turn. The troll has 1 Exhaustion level for each missing limb, and it grows replacement limbs the next time it regains Hit Points."},{"name":"Regeneration","text":"The troll regains 15 Hit Points at the start of each of its turns. If the troll takes Acid or Fire damage, this trait doesn’t function on the troll’s next turn. The troll dies only if it starts its turn with 0 Hit Points and doesn’t regenerate."}]},
